import React from "react";
import Banner from "./Banner";
import "../styles/main.css";

const Academics = () => {
  return (
    <>
      <Banner /> {/* ✅ added */}
      <main className="main-container">
        <div className="two-column">
          <div className="left-column">
            <h2>Academics</h2>
            <div className="points-box">
              <p>Pedagogy</p>
              <p>Annual Calendar</p>
              <p>Result</p>
            </div>
          </div>
          <div className="right-column">
            <h2>Pedagogy</h2>
            <p>
              Our management council is seasoned and learned team of experts who have
              been into teacher training for 12+ years. "From 12 years we have made
              best teachers and now we'll make the best school for intelligent &
              compassionate kids ready for 21st century."
            </p>
            <h3>CCE Pattern of CBSE</h3>
            <p>
              Continuous and Comprehensive Evaluation (CCE) helps reduce pressure on
              students and evaluates every aspect of the child.{" "}
              <a href="http://www.cbse.nic.in/cce/index.html" target="_blank" rel="noreferrer">
                Read more
              </a>
            </p>
            <h3>Other International Approaches</h3>
            <p>
              Reggio Emilia, Montessori & Waldorf approaches are incorporated for
              developing leadership, independence, and citizenship qualities.
            </p>
            <h3>Smart Classes</h3>
            <p>
              Technology helps students gain insight and clarity in concepts. Smart
              classes improve retention compared to ordinary teaching methods.
            </p>
            <h3>Remedial Classes</h3>
            <p>
              Remedial classes are used to identify student problem areas and provide
              better understanding of concepts.
            </p>
          </div>
        </div>
      </main>
      
    </>
  );
};

export default Academics;







